 "content": "def transform(grid):
    # Locate sparse row immediately preceding a large run of uniform pattern
    # cells; in examples the run's color is the foreground and the row is the
    # seed/template row. Extend the vertical periodic pattern below it, coloring
    # cells matching the sparse template's periodic positions with 1.
    out=[r[:] for r in grid]
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    # Find rows with a long uninterrupted run of non-background pixels.
    for r in range(h-1):
        runs=[]; c=0
        while c<w:
            if grid[r][c]!=bg:
                s=c
                while c<w and grid[r][c]!=bg: c+=1
                if c-s>=w//3: runs.append((s,c))
            else:c+=1
        if not runs: continue
        # The long run is the horizontal filled strip. Beneath it, repeat the
        # sparse 2-cell motif of the row above/below, replacing foreground hits.
        for s,e in runs:
            if r+1<h:
                for rr in range(r+1,h):
                    for cc in range(s,e):
                        if grid[rr][cc]!=bg:
                            out[rr][cc]=1
        break
    return out
