 "content": "def transform(grid):
    # Find a large solid foreground strip followed below by a sparse repeating
    # motif. In the examples, the strip is the target paint: its color becomes
    # 1, and the corresponding foreground pixels of the repeated lower pattern
    # are also marked 1. Keep other cells unchanged.
    from collections import Counter
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find all-background separator rows and examine each nonempty block.
    active=[r for r in range(h) if any(v!=bg for v in grid[r])]
    bands=[]
    for r in active:
        if not bands or r>bands[-1][-1]+1: bands.append([r])
        else: bands[-1].append(r)
    # In large tiled task, alternating same motif bands encode target region.
    # Demonstrations indicate recolor the sparse horizontal tail in first band.
    for band in bands:
        # Detect runs of foreground or background anomalously extended to edge;
        # those form the stripe to recolor.
        for r in band:
            vals=grid[r]
            # longest run of non-background cells, typical repeated motif line
            best=(0,0,0); c=0
            while c<w:
                if vals[c]!=bg:
                    s=c
                    while c<w and vals[c]!=bg: c+=1
                    if c-s>best[2]: best=(s,c,c-s)
                else:c+=1
            # Do not recolor short motif runs; marker is contiguous trailing block.
            if best[2]>=w//3 and best[1]==w:
                for c in range(best[0],w):
                    if vals[c]!=bg: out[r][c]=1
        # only process the first pattern cluster
        if band: break
    return out
